<script module lang="ts">
/**
 * A number field that formats and steps (`design/components/number-input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/number-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import * as zag from '@zag-js/number-input'
import { useMachine } from '@zag-js/svelte'

import {
  Icon,
  agentMember,
  attributes,
  joinSlot,
  mergeParts,
  normalizeProps,
  useDirection,
  watchEffect,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/controls/number-input.module.css'

export interface NumberFormat {
  style?: 'decimal' | 'percent' | 'currency'
  currency?: string
  maximumFractionDigits?: number
}

export interface NumberInputMessages {
  increment?: string
  decrement?: string
}

export interface NumberInputProps {
  'aria-describedby'?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  defaultValue?: number | null
  disabled?: boolean
  /**
   * The chart tier's format descriptor, limited to what an editable field can parse back. It
   * formats the displayed text only. The committed value is always the raw number. Raw
   * `Intl.NumberFormatOptions` are not accepted.
   */
  format?: NumberFormat
  id?: string
  invalid?: boolean
  max?: number
  /**
   * The steppers' names in the host's words.
   */
  messages?: NumberInputMessages
  /**
   * Typed values are clamped at commit. The steppers snap to the step and stop at the limits.
   */
  min?: number
  /**
   * Posts the **plain number** on a hidden input, never the formatted text.
   */
  name?: string
  /**
   * Fires after the commit settles, so touched validation reads the committed number.
   */
  onBlur?: (event: FocusEvent) => void
  /**
   * Reports committed numbers only, never unparsed text and never `NaN`.
   */
  onChange?: (value: number | null) => void
  onFocus?: (event: FocusEvent) => void
  placeholder?: string
  /**
   * Affixes as defined in `input.md`: strings only, muted, and `aria-hidden`. Use `format`
   * first. Affixes are for units Intl cannot format ("/mo", "per seat").
   */
  prefix?: string
  /**
   * Hides the steppers, because a value that cannot be edited cannot be stepped.
   */
  readOnly?: boolean
  size?: 'sm' | 'md' | 'lg'
  step?: number
  suffix?: string
  /**
   * `null` is the empty field.
   */
  value?: number | null
}
</script>

<script lang="ts">
let {
  'aria-describedby': ariaDescribedbyOwn,
  'aria-label': ariaLabel,
  'aria-labelledby': ariaLabelledbyOwn,
  'aria-required': ariaRequiredOwn,
  defaultValue,
  disabled = false,
  format,
  id: idOwn,
  invalid: invalidOwn = false,
  max,
  messages,
  min,
  name,
  onBlur,
  onChange,
  onFocus,
  placeholder,
  prefix,
  readOnly = false,
  size = 'md',
  step,
  suffix,
  value,
}: NumberInputProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({ disabled: disabled, name: name, size: size }))
const ariaDescribedby = $derived(
  joined.passed['aria-describedby'] === undefined
    ? ariaDescribedbyOwn
    : (joined.passed['aria-describedby'] as typeof ariaDescribedbyOwn),
)
const ariaLabelledby = $derived(
  joined.passed['aria-labelledby'] === undefined
    ? ariaLabelledbyOwn
    : (joined.passed['aria-labelledby'] as typeof ariaLabelledbyOwn),
)
const ariaRequired = $derived(
  joined.passed['aria-required'] === undefined
    ? ariaRequiredOwn
    : (joined.passed['aria-required'] as typeof ariaRequiredOwn),
)
const id = $derived(
  joined.passed['id'] === undefined ? idOwn : (joined.passed['id'] as typeof idOwn),
)
const invalid = $derived(
  joined.passed['invalid'] === undefined
    ? invalidOwn
    : (joined.passed['invalid'] as typeof invalidOwn),
)
// svelte-ignore state_referenced_locally
let committed = $state(value === undefined ? (defaultValue ?? null) : value)
let draft = $state('')
let control = $state<HTMLElement | null>(null)
const say = $derived({ increment: 'increment value', decrement: 'decrease value', ...messages })
const documentDirection = useDirection(() => control)
const service = useMachine(
  zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      defaultValue:
        (value === undefined ? defaultValue : value) === undefined
          ? undefined
          : (value === undefined ? defaultValue : value) === null
            ? ''
            : String(value === undefined ? defaultValue : value),
      min: min,
      max: max,
      step: step,
      formatOptions: format,
      disabled: disabled,
      readOnly: readOnly,
      invalid: invalid,
      required: ariaRequired,
      allowMouseWheel: false,
      ids: id === undefined ? undefined : { input: id },
      translations: { incrementLabel: say.increment, decrementLabel: say.decrement },
      onValueChange: (details) => {
        service.event.current().type === 'INPUT.CHANGE'
          ? (draft = details.value)
          : ['INPUT.BLUR', 'INPUT.ENTER', 'VALUE.SET', 'VALUE.CLEAR'].includes(
              service.event.current().type,
            ) ||
            ((next) => next === committed || ((committed = next), onChange?.(next)))(
              Number.isNaN(details.valueAsNumber) ? null : details.valueAsNumber,
            )
      },
      onValueCommit: (details) => {
        Number.isNaN(details.valueAsNumber) && draft.trim() !== ''
          ? committed === null
            ? api.clearValue()
            : api.setValue(committed)
          : ((next) => next === committed || ((committed = next), onChange?.(next)))(
              Number.isNaN(details.valueAsNumber) ? null : details.valueAsNumber,
            )
      },
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
const effect1 = () => {
  value === undefined ||
    value === committed ||
    ((committed = value), value === null ? api.clearValue() : api.setValue(value))
}
watchEffect(effect1, { watch: () => [value, committed], mount: false })
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = agentMember({
    member: 'NumberInput',
    element: () => control,
    state: () => ({ value: committed, disabled: disabled, invalid: invalid, readonly: readOnly }),
    actions: {
      set: {
        argument: 'number',
        run: (value) =>
          (() => {
            if (readOnly) throw new Error('The field is read-only.')
            const next = Math.min(Math.max(value, min ?? -Infinity), max ?? Infinity)
            api.setValue(next)
            ;((next) => next === committed || ((committed = next), onChange?.(next)))(
              Number.isNaN(next) ? null : next,
            )
          })(),
      },
      clear: () =>
        (() => {
          if (readOnly) throw new Error('The field is read-only.')
          api.clearValue()
          ;((next) => next === committed || ((committed = next), onChange?.(next)))(
            Number.isNaN(NaN) ? null : NaN,
          )
        })(),
    },
  })
  release2 = () => {
    ran()
  }
}
watchEffect(effect2)
onDestroy(() => release2?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    {...attributes(mergeParts(api.getRootProps(), { onMousedown: (event: MouseEvent) => { if (!(event.composedPath().some((node) => 'nodeName' in node && ['BUTTON', 'A', 'INPUT', 'SELECT', 'TEXTAREA'].includes(String(node.nodeName))))) (event.preventDefault(), api.focus()) } }))}
    class={styles.field}
    data-size={size}
    data-disabled={(disabled) ? '' : undefined}
    data-invalid={(invalid) ? '' : undefined}
    data-readonly={(readOnly) ? '' : undefined}
    data-member="number-input"
    >{#if prefix !== undefined}<span class={styles.affix} aria-hidden="true">{prefix}</span>{/if
    }<input
      bind:this={control}
      {...attributes(mergeParts(api.getInputProps(), { onBlur: (event: FocusEvent) => { onBlur?.(event) }, onFocus: (event: FocusEvent) => { onFocus?.(event) } }))}
      class={styles.input}
      name={undefined}
      {placeholder}
      role={undefined}
      aria-roledescription={undefined}
      aria-valuemin={undefined}
      aria-valuemax={undefined}
      aria-valuenow={undefined}
      aria-valuetext={undefined}
      aria-label={ariaLabel}
      aria-labelledby={ariaLabelledby}
      aria-describedby={ariaDescribedby}
      aria-required={ariaRequired}
    />{#if suffix !== undefined}<span class={styles.affix} aria-hidden="true">{suffix}</span>{/if
    }{#if !readOnly
      }<div class={styles.steppers}
        ><button {...attributes(api.getDecrementTriggerProps())} class={styles.stepper}
          ><Icon name="down" {size}
        /></button
        ><button {...attributes(api.getIncrementTriggerProps())} class={styles.stepper}
          ><Icon name="up" {size}
        /></button
      ></div
    >{/if
    }{#if name !== undefined
      }<input type="hidden" {name} value={committed ?? ''} disabled={disabled || undefined}
    />{/if
  }</div
>{/if
}{@render joined.end?.()}
